select public.seed_wines('[{"s":"marcel-lapierre-morgon","n":"Morgon","p":"Marcel Lapierre","t":"red","c":"France","r":"Beaujolais","a":"Morgon","g":["Gamay"],"pr":33,"abv":13,"e":"Whole-cluster semi-carbonic fermentation; aged in old Burgundy barrels and foudres with minimal sulfur","sv":"13–15°C","d":"Optional, 30 minutes","w":"Now–8 years","ds":"The founding text of natural Beaujolais: whole-cluster Gamay that smells of crushed raspberry, cherry and peony with a faint wild, earthy edge. Juicy and almost weightless at first, it reveals a granitic, iron-tinged core that keeps it serious.","x":"284:2,285:65,286:35,287:45,288:45,289:62,290:55,291:8,292:0,293:15,1:70,3:55,14:45,5:35,8:20,71:35,82:25,72:20,151:35,140:30,143:15,120:12,229:80,212:45,231:50,240:75,252:55,256:70,248:40,253:25,263:85,262:60,265:85,260:40,279:65,283:70,301:100,298:100,296:100,318:100"},{"s":"chateau-de-la-chaize-brouilly","n":"Brouilly","p":"Château de la Chaize","t":"red","c":"France","r":"Beaujolais","a":"Brouilly","g":["Gamay"],"pr":20,"abv":13,"e":"Partial semi-carbonic fermentation in concrete; aged in tank and large old oak","sv":"13–15°C","d":"Not needed","w":"Now–4 years","ds":"Brouilly at its most cheerful: a basket of raspberry and red cherry, a hint of violet and white pepper, and almost no tannic friction. Lightly chilled, it is the definition of a wine that disappears from the bottle.","x":"284:2,285:60,286:28,287:42,288:35,289:50,290:42,291:5,292:0,293:12,3:75,1:65,4:50,6:30,9:25,63:12,71:20,121:12,151:15,229:80,231:55,212:35,240:80,244:80,256:95,263:55,260:30,279:85,283:95,301:100,298:100,302:100,296:100"},{"s":"clos-de-la-roilette-fleurie","n":"Fleurie","p":"Clos de la Roilette (Coudert)","t":"red","c":"France","r":"Beaujolais","a":"Fleurie","g":["Gamay"],"pr":28,"abv":13,"e":"Traditional semi-carbonic fermentation; aged in large old foudres","sv":"13–15°C","d":"Optional, 30 minutes","w":"Now–10 years","ds":"Fleurie from the Moulin-à-Vent border, so the violet and peony perfume rides on a sturdier, stonier frame than most of the cru. Red and black cherry, crushed granite and fine tannins make it Beaujolais that rewards a few years in bottle.","x":"284:2,285:63,286:40,287:45,288:45,289:60,290:58,291:6,292:0,293:15,1:65,3:50,14:45,9:35,71:75,82:50,72:40,81:30,140:35,151:25,143:12,135:12,212:55,214:30,229:60,252:85,236:60,240:65,245:40,258:60,263:40,260:55,282:45,279:60,298:100,296:100,299:100,310:100"},{"s":"chateau-des-jacques-moulin-a-vent","n":"Moulin-à-Vent","p":"Château des Jacques (Louis Jadot)","t":"red","c":"France","r":"Beaujolais","a":"Moulin-à-Vent","g":["Gamay"],"pr":30,"abv":13.5,"e":"Destemmed with traditional Burgundian maceration; 9–12 months in barrel, a portion new","sv":"14–16°C","d":"30–60 minutes when young","w":"2–12 years","ds":"Gamay vinified like Burgundy: black cherry and plum, violet, and a ferrous, granitic seam from manganese-rich soils, framed by a touch of toasty oak. Firmer and darker than most Beaujolais, it ages toward something that can pass for Côte de Nuits.","x":"284:2,285:60,286:55,287:50,288:58,289:65,290:62,291:30,292:0,293:18,14:70,1:50,15:45,12:30,3:30,71:50,81:20,140:45,143:30,151:35,148:20,126:15,135:25,157:15,156:12,214:60,216:30,245:70,255:45,242:30,258:55,243:40,259:25,260:35,282:70,279:60,299:100,294:100,297:100,310:100,296:100"},{"s":"louis-bouillot-perle-d-ivoire-cremant-de-bourgogne","n":"Perle d''Ivoire Brut","p":"Louis Bouillot","t":"sparkling","c":"France","r":"Burgundy","a":"Crémant de Bourgogne","g":["Pinot Noir","Chardonnay","Gamay","Aligoté"],"pr":20,"abv":12,"e":"Traditional method; at least 12 months on lees","sv":"6–8°C","d":"Not needed","w":"Now–3 years","ds":"Burgundy''s answer to everyday Champagne: crisp green apple, pear and lemon with a light bread-dough note from time on the lees. The mousse is lively rather than fine, and the finish is clean and refreshing.","x":"284:8,285:80,286:2,287:38,288:38,289:50,290:48,291:0,292:90,293:18,46:65,47:40,49:45,34:55,53:25,85:30,73:15